#include "qa/VerticalSliceScenario.hpp"
#include <algorithm>
namespace elysium::qa { namespace{std::uint64_t mix(std::uint64_t x){x^=x>>30;x*=0xbf58476d1ce4e5b9ULL;x^=x>>27;x*=0x94d049bb133111ebULL;return x^(x>>31);}} SliceAcceptance::SliceAcceptance(SliceFixture f):fixture_(f){} bool SliceAcceptance::record(GateEvidence e){if(e.ownerPackage.empty()&&e.state!=GateState::MissingOwner)e.state=GateState::MissingOwner;gates_[e.gate]=std::move(e);return true;} std::vector<GateEvidence> SliceAcceptance::readiness()const{std::vector<GateEvidence>o;for(auto g:requiredSliceGates()){auto it=gates_.find(g);o.push_back(it==gates_.end()?GateEvidence{g,GateState::NotRun,"","","not recorded"}:it->second);}return o;} bool SliceAcceptance::complete()const{auto r=readiness();return std::all_of(r.begin(),r.end(),[](auto&e){return e.state==GateState::Pass;});} std::uint64_t SliceAcceptance::fingerprint()const noexcept{return mix(fixture_.seed^mix(fixture_.temperateId)^mix(fixture_.barrenId)^mix(fixture_.hazardousId));} std::vector<SliceGate> requiredSliceGates(){std::vector<SliceGate>o;for(unsigned i=0;i<=unsigned(SliceGate::ThreePlanetDifferentiation);++i)o.push_back(static_cast<SliceGate>(i));return o;} }
